import { Request, Response } from 'express';
import { asyncHandler } from '../utils/asyncHandler';
import * as mediaService from '../services/media.service';
import { Role } from '@prisma/client';

/**
 * 扩展Express Request类型以包含user属性
 */
interface AuthenticatedRequest extends Request {
  user?: {
    userId: number;
    role: string;
  };
}

/**
 * 上传文件
 */
export const uploadFile = asyncHandler(async (req: AuthenticatedRequest, res: Response) => {
  // 确保用户已认证
  if (!req.user) {
    res.status(401).json({
      success: false,
      error: '需要登录才能上传文件',
    });
    return;
  }

  // 检查是否有文件上传
  if (!req.file) {
    res.status(400).json({
      success: false,
      error: '请选择要上传的文件',
    });
    return;
  }

  const file = await mediaService.saveFile({
    file: req.file,
    uploaderId: req.user.userId,
  });

  res.status(201).json({
    success: true,
    data: file,
  });
});

/**
 * 获取单个文件信息
 */
export const getFile = asyncHandler(async (req: Request, res: Response) => {
  const fileId = parseInt(req.params.id);
  if (isNaN(fileId)) {
    res.status(400).json({
      success: false,
      error: '无效的文件ID',
    });
    return;
  }

  const file = await mediaService.getFileById(fileId);
  res.status(200).json({
    success: true,
    data: file,
  });
});

/**
 * 获取文件列表（支持分页、筛选）
 */
export const getFiles = asyncHandler(async (req: Request, res: Response) => {
  const {
    page = '1',
    limit = '10',
    uploaderId,
    mimeType,
    sortBy = 'createdAt',
    sortOrder = 'desc',
  } = req.query;

  const params: mediaService.GetFilesParams = {
    page: parseInt(page as string) || 1,
    limit: parseInt(limit as string) || 10,
    uploaderId: uploaderId ? parseInt(uploaderId as string) : undefined,
    mimeType: mimeType as string,
    sortBy: sortBy as 'createdAt' | 'filename',
    sortOrder: sortOrder as 'asc' | 'desc',
  };

  const result = await mediaService.getFiles(params);
  res.status(200).json({
    success: true,
    data: result,
  });
});

/**
 * 删除文件
 */
export const deleteFile = asyncHandler(async (req: AuthenticatedRequest, res: Response) => {
  const fileId = parseInt(req.params.id);
  if (isNaN(fileId)) {
    res.status(400).json({
      success: false,
      error: '无效的文件ID',
    });
    return;
  }

  if (!req.user) {
    res.status(401).json({
      success: false,
      error: '需要登录才能删除文件',
    });
    return;
  }

  await mediaService.deleteFile(fileId, req.user.userId, req.user.role as Role);
  res.status(200).json({
    success: true,
    message: '文件删除成功',
  });
});

/**
 * 获取用户上传的文件列表
 */
export const getUserFiles = asyncHandler(async (req: AuthenticatedRequest, res: Response) => {
  const userId = parseInt(req.params.userId);
  if (isNaN(userId)) {
    res.status(400).json({
      success: false,
      error: '无效的用户ID',
    });
    return;
  }

  // 检查权限：用户只能查看自己的文件，管理员可以查看任何用户的文件
  if (req.user?.role !== Role.ADMIN && req.user?.userId !== userId) {
    res.status(403).json({
      success: false,
      error: '您只能查看自己的文件',
    });
    return;
  }

  const {
    page = '1',
    limit = '10',
    mimeType,
    sortBy = 'createdAt',
    sortOrder = 'desc',
  } = req.query;

  const params: mediaService.GetFilesParams = {
    page: parseInt(page as string) || 1,
    limit: parseInt(limit as string) || 10,
    uploaderId: userId,
    mimeType: mimeType as string,
    sortBy: sortBy as 'createdAt' | 'filename',
    sortOrder: sortOrder as 'asc' | 'desc',
  };

  const result = await mediaService.getFiles(params);
  res.status(200).json({
    success: true,
    data: result,
  });
});

/**
 * 更新文件信息
 */
export const updateFileInfo = asyncHandler(async (req: AuthenticatedRequest, res: Response) => {
  const fileId = parseInt(req.params.id);
  if (isNaN(fileId)) {
    res.status(400).json({
      success: false,
      error: '无效的文件ID',
    });
    return;
  }

  if (!req.user) {
    res.status(401).json({
      success: false,
      error: '需要登录才能更新文件信息',
    });
    return;
  }

  const { filename } = req.body;
  if (!filename || typeof filename !== 'string') {
    res.status(400).json({
      success: false,
      error: '文件名不能为空',
    });
    return;
  }

  const updatedFile = await mediaService.updateFileInfo(
    fileId,
    { filename },
    req.user.userId,
    req.user.role as Role
  );
  res.status(200).json({
    success: true,
    data: updatedFile,
  });
});

