import { Media, Role } from '@prisma/client';
import prisma from '../db';
import { BadRequestError, ForbiddenError, NotFoundError } from '../utils/AppError';
import { createPaginatedResponse, buildPaginationOptions } from '../db';
import fs from 'fs/promises';
import path from 'path';
import { v4 as uuidv4 } from 'uuid';

/**
 * 文件上传输入接口
 */
export interface SaveFileInput {
  file: Express.Multer.File;
  uploaderId: number;
}

/**
 * 文件查询参数接口
 */
export interface GetFilesParams {
  page?: number;
  limit?: number;
  uploaderId?: number;
  mimeType?: string;
  sortBy?: 'createdAt' | 'filename';
  sortOrder?: 'asc' | 'desc';
}

/**
 * 分页文件列表返回接口
 */
export interface PaginatedFiles {
  items: Media[];
  total: number;
  page: number;
  limit: number;
  totalPages: number;
  hasNext: boolean;
  hasPrev: boolean;
}

/**
 * 更新文件信息输入接口
 */
export interface UpdateFileInfoInput {
  filename?: string;
}

/**
 * 允许的文件MIME类型
 */
const ALLOWED_MIME_TYPES = [
  'image/jpeg',
  'image/png',
  'image/gif',
  'image/webp',
  'image/svg+xml',
  'application/pdf',
  'text/plain',
  'application/msword',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  'application/vnd.ms-excel',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  'application/zip',
  'application/x-rar-compressed',
];

/**
 * 最大文件大小（10MB）
 */
const MAX_FILE_SIZE = 10 * 1024 * 1024; // 10MB in bytes

/**
 * 获取上传目录路径（按年/月/日组织）
 */
function getUploadDir(date = new Date()): string {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return path.join('uploads', String(year), month, day);
}

/**
 * 生成唯一的文件名
 */
function generateUniqueFilename(originalName: string): string {
  const ext = path.extname(originalName);
  const baseName = path.basename(originalName, ext);
  const sanitizedBaseName = baseName.replace(/[^a-zA-Z0-9-_]/g, '_').substring(0, 100);
  const uuid = uuidv4().replace(/-/g, '');
  return `${sanitizedBaseName}_${uuid}${ext}`;
}

/**
 * 确保目录存在
 */
async function ensureDirectoryExists(dirPath: string): Promise<void> {
  try {
    await fs.access(dirPath);
  } catch {
    await fs.mkdir(dirPath, { recursive: true });
  }
}

/**
 * 验证文件
 */
function validateFile(file: Express.Multer.File): void {
  // 验证文件大小
  if (file.size > MAX_FILE_SIZE) {
    throw new BadRequestError(`文件大小超过限制（最大${MAX_FILE_SIZE / 1024 / 1024}MB）`);
  }

  // 验证MIME类型
  if (!ALLOWED_MIME_TYPES.includes(file.mimetype)) {
    throw new BadRequestError(`不支持的文件类型：${file.mimetype}`);
  }
}

/**
 * 保存文件到磁盘并记录到数据库
 */
export async function saveFile(input: SaveFileInput): Promise<Media> {
  const { file, uploaderId } = input;

  // 验证文件
  validateFile(file);

  // 生成存储路径
  const uploadDir = getUploadDir();
  const absoluteUploadDir = path.join(__dirname, '..', '..', uploadDir);
  await ensureDirectoryExists(absoluteUploadDir);

  // 生成唯一文件名
  const uniqueFilename = generateUniqueFilename(file.originalname);
  const filepath = path.join(uploadDir, uniqueFilename);
  const absoluteFilepath = path.join(absoluteUploadDir, uniqueFilename);

  // 将文件从临时位置移动到目标位置
  await fs.copyFile(file.path, absoluteFilepath);
  // 删除临时文件（可选，multer可能会自动清理）
  try {
    await fs.unlink(file.path);
  } catch (error) {
    // 忽略错误
  }

  // 保存文件信息到数据库
  const media = await prisma.media.create({
    data: {
      filename: file.originalname,
      filepath: filepath.replace(/\\/g, '/'), // 统一使用斜杠
      mimeType: file.mimetype,
      size: file.size,
      uploaderId,
    },
    include: {
      uploader: {
        select: {
          id: true,
          name: true,
          email: true,
        },
      },
    },
  });

  return media;
}

/**
 * 根据ID获取文件信息
 */
export async function getFileById(fileId: number): Promise<Media> {
  const file = await prisma.media.findUnique({
    where: { id: fileId },
    include: {
      uploader: {
        select: {
          id: true,
          name: true,
          email: true,
        },
      },
    },
  });

  if (!file) {
    throw new NotFoundError('文件不存在');
  }

  return file;
}

/**
 * 获取文件列表（分页）
 */
export async function getFiles(params: GetFilesParams): Promise<PaginatedFiles> {
  const { page = 1, limit = 10, uploaderId, mimeType, sortBy = 'createdAt', sortOrder = 'desc' } = params;
  const { skip, take } = buildPaginationOptions({ page, pageSize: limit });

  const where = {
    uploaderId,
    mimeType: mimeType ? { contains: mimeType } : undefined,
  };

  const [files, total] = await Promise.all([
    prisma.media.findMany({
      where,
      skip,
      take,
      orderBy: { [sortBy]: sortOrder },
      include: {
        uploader: {
          select: {
            id: true,
            name: true,
            email: true,
          },
        },
      },
    }),
    prisma.media.count({ where }),
  ]);

  return {
    items: files,
    total,
    page,
    limit,
    totalPages: Math.ceil(total / limit),
    hasNext: page < Math.ceil(total / limit),
    hasPrev: page > 1,
  };
}

/**
 * 删除文件（同时删除物理文件）
 */
export async function deleteFile(fileId: number, userId: number, userRole: Role): Promise<void> {
  // 获取文件信息
  const file = await prisma.media.findUnique({
    where: { id: fileId },
  });

  if (!file) {
    throw new NotFoundError('文件不存在');
  }

  // 检查权限：上传者或管理员可以删除
  if (file.uploaderId !== userId && userRole !== Role.ADMIN) {
    throw new ForbiddenError('您没有权限删除此文件');
  }

  // 删除物理文件
  const absoluteFilepath = path.join(__dirname, '..', '..', file.filepath);
  try {
    await fs.access(absoluteFilepath);
    await fs.unlink(absoluteFilepath);
  } catch (error) {
    // 如果文件不存在，仅记录警告，继续删除数据库记录
    console.warn(`物理文件不存在：${absoluteFilepath}`);
  }

  // 删除数据库记录
  await prisma.media.delete({
    where: { id: fileId },
  });
}

/**
 * 更新文件信息
 */
export async function updateFileInfo(
  fileId: number,
  updateData: UpdateFileInfoInput,
  userId: number,
  userRole: Role
): Promise<Media> {
  // 获取文件信息
  const file = await prisma.media.findUnique({
    where: { id: fileId },
  });

  if (!file) {
    throw new NotFoundError('文件不存在');
  }

  // 检查权限：上传者或管理员可以更新
  if (file.uploaderId !== userId && userRole !== Role.ADMIN) {
    throw new ForbiddenError('您没有权限更新此文件信息');
  }

  // 更新数据库记录
  const updatedFile = await prisma.media.update({
    where: { id: fileId },
    data: {
      filename: updateData.filename,
    },
    include: {
      uploader: {
        select: {
          id: true,
          name: true,
          email: true,
        },
      },
    },
  });

  return updatedFile;
}

