import { Router } from 'express';
import multer from 'multer';
import path from 'path';
import * as mediaController from '../controllers/media.controller';
import * as mediaValidation from '../validations/media.validation';
import { requireAuth } from '../middleware/auth';
import { validate } from '../middleware/validate';

const router = Router();

/**
 * Multer配置
 * 使用内存存储，因为文件将在服务层中处理
 */
const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    // 临时目录
    cb(null, path.join(__dirname, '../../uploads/temp'));
  },
  filename: (req, file, cb) => {
    // 保留原始文件名，添加时间戳防止冲突
    const timestamp = Date.now();
    const ext = path.extname(file.originalname);
    const name = path.basename(file.originalname, ext);
    const sanitizedName = name.replace(/[^a-zA-Z0-9-_]/g, '_');
    cb(null, `${sanitizedName}_${timestamp}${ext}`);
  },
});

// 文件过滤器
const fileFilter = (req: any, file: Express.Multer.File, cb: multer.FileFilterCallback) => {
  // 允许的文件类型
  const allowedMimeTypes = [
    'image/jpeg',
    'image/png',
    'image/gif',
    'image/webp',
    'image/svg+xml',
    'application/pdf',
    'text/plain',
    'application/msword',
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    'application/vnd.ms-excel',
    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    'application/zip',
    'application/x-rar-compressed',
  ];

  if (allowedMimeTypes.includes(file.mimetype)) {
    cb(null, true);
  } else {
    cb(new Error(`不支持的文件类型：${file.mimetype}`));
  }
};

const upload = multer({
  storage,
  fileFilter,
  limits: {
    fileSize: 10 * 1024 * 1024, // 10MB
  },
});

/**
 * @route POST /api/media/upload
 * @desc 上传文件
 * @access Private
 */
router.post(
  '/upload',
  requireAuth,
  upload.single('file'),
  mediaController.uploadFile
);

/**
 * @route GET /api/media/:id
 * @desc 获取文件信息
 * @access Public
 */
router.get(
  '/:id',
  mediaValidation.fileIdValidation,
  validate,
  mediaController.getFile
);

/**
 * @route GET /api/media
 * @desc 获取文件列表（支持分页、筛选）
 * @access Public (或受限)
 */
router.get(
  '/',
  mediaValidation.getFilesValidation,
  validate,
  mediaController.getFiles
);

/**
 * @route DELETE /api/media/:id
 * @desc 删除文件
 * @access Private (上传者或管理员)
 */
router.delete(
  '/:id',
  requireAuth,
  mediaValidation.fileIdValidation,
  validate,
  mediaController.deleteFile
);

/**
 * @route PUT /api/media/:id
 * @desc 更新文件信息
 * @access Private (上传者或管理员)
 */
router.put(
  '/:id',
  requireAuth,
  mediaValidation.updateFileValidation,
  validate,
  mediaController.updateFileInfo
);

/**
 * @route GET /api/users/:userId/media
 * @desc 获取用户上传的文件列表
 * @access Private (用户自己或管理员)
 */
router.get(
  '/users/:userId/media',
  requireAuth,
  mediaValidation.userIdValidation,
  validate,
  mediaController.getUserFiles
);

export default router;

