const upload = multer({
  storage,
  fileFilter,
  limits: {
    fileSize: 10 * 1024 * 1024, // 10MB
  },
});

/**
 * @route POST /api/media/upload
 * @desc 上传文件
 * @access Private
 */
router.post(
  '/upload',
  requireAuth,
  upload.single('file'),
  mediaController.uploadFile
);

/**
 * @route GET /api/media/:id
 * @desc 获取文件信息
 * @access Public
 */
router.get(
  '/:id',
  mediaValidation.fileIdValidation,
  validate,
  mediaController.getFile
);

/**
 * @route GET /api/media
 * @desc 获取文件列表（支持分页、筛选）
 * @access Public (或受限)
 */
router.get(
  '/',
  mediaValidation.getFilesValidation,
  validate,
  mediaController.getFiles
);

/**
 * @route DELETE /api/media/:id
 * @desc 删除文件
 * @access Private (上传者或管理员)
 */
router.delete(
  '/:id',
  requireAuth,
  mediaValidation.fileIdValidation,
  validate,
  mediaController.deleteFile
);

/**
 * @route PUT /api/media/:id
 * @desc 更新文件信息
 * @access Private (上传者或管理员)
 */
router.put(
  '/:id',
  requireAuth,
  mediaValidation.updateFileValidation,
  validate,
  mediaController.updateFileInfo
);

/**
 * @route GET /api/users/:userId/media
 * @desc 获取用户上传的文件列表
 * @access Private (用户自己或管理员)
 */
router.get(
  '/users/:userId/media',
  requireAuth,
  mediaValidation.userIdValidation,
  validate,
  mediaController.getUserFiles
);

export default router;

